const SLUG = 'pay-off-home-loan-or-invest'
const OLD_SLUG = 'how-long-will-my-money-last-invest-or-pay-off-mortgage'
const CONTENT = {"root": {"type": "root", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "quote", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "The short answer:", "format": 1, "detail": 0, "mode": "normal", "style": "", "version": 1}, {"type": "text", "text": " there's no single right answer. If your home loan's interest rate is low, investing at least part of the money has historically had more potential over the long run. But if being loan-free would let you sleep better at night, paying it off is a perfectly good decision, and many people do a bit of both.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}]}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "A reader wrote to me with a problem most people would love to have. He's 30. He had just inherited enough money to clear the home loan he and his wife took out five years ago. All of it.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "\"Just thinking about it feels incredible,\" he wrote. No monthly repayment. No 25 more years of instalments. And yet he couldn't decide. Because over the past few months he had started reading about investing, and a quiet voice kept asking: what if this money could do more?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "So which is it? Pay off the house, or invest?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Firstly, paying off your home is never a bad decision", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h2"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Let me say this clearly, because people often expect me to say the opposite. Owning your home outright is a wonderful feeling. Your monthly costs drop. Your stress drops. And you can never lose your home to a repayment you can't make.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "If being loan-free has always been your main financial goal, and you know you'd sleep better, then go for it. Money is supposed to serve your life, not the other way round.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Having said that, here's the case for investing", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h2"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Home loans in Malta tend to carry relatively low interest rates. When the money you'd use to clear the loan could potentially grow faster than the interest you're paying, keeping the loan and investing has historically had more upside over the long term.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Take the S&P 500, the index of America's largest listed companies. Over the past several decades it has averaged roughly 8% to 10% a year. Does that mean 8% to 10% every year? Not at all. Some years it fell hard. Others it jumped. But over long periods, the average held.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "And at 30, you have something money can't buy: time.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Why time matters more than the amount", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h2"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Meet Paul and Laureen. Both invest €2,400 a year. The only difference is when they start.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "list", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "listitem", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Paul", "format": 1, "detail": 0, "mode": "normal", "style": "", "version": 1}, {"type": "text", "text": " starts at 21 and stops at 29. He puts in €21,600 in total. At 67 he has about ", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}, {"type": "text", "text": "€558,000", "format": 1, "detail": 0, "mode": "normal", "style": "", "version": 1}, {"type": "text", "text": ".", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "value": 1}, {"type": "listitem", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Laureen", "format": 1, "detail": 0, "mode": "normal", "style": "", "version": 1}, {"type": "text", "text": " starts at 30 and keeps going until 66. She puts in €88,800 in total. At 67 she has about ", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}, {"type": "text", "text": "€526,000", "format": 1, "detail": 0, "mode": "normal", "style": "", "version": 1}, {"type": "text", "text": ".", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "value": 2}], "listType": "bullet", "start": 1, "tag": "ul"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Paul invests four times less and still ends up ahead, simply because his money had nine extra years to grow. That's compound growth: your returns start earning returns of their own.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Illustration only. It assumes a steady 8% a year, which markets never deliver in a straight line, and ignores fees, tax and inflation.", "format": 2, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "The middle road most people miss", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h2"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "It doesn't have to be all or nothing. You could pay off a large chunk of the loan and ask your bank to lower your monthly repayment, keeping the same term. Your monthly bill shrinks, you feel lighter, and you keep money aside to start investing.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "And if you do invest, there's no need to throw it all in on one day. Many people put in a fixed amount every month instead. It's called dollar-cost averaging, and it makes the ups and downs of the market far easier to live with.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Five questions to ask yourself before you decide", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h2"}, {"type": "list", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "listitem", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "What interest rate am I actually paying on my home loan?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "value": 1}, {"type": "listitem", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Do I have three to six months of expenses saved as an emergency fund, separate from this money?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "value": 2}, {"type": "listitem", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "How would I honestly feel if my investments dropped by 20% in a single year?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "value": 3}, {"type": "listitem", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Can I leave this money invested for at least ten years?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "value": 4}, {"type": "listitem", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "What does my partner want? (This one matters more than the maths.)", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "value": 5}], "listType": "bullet", "start": 1, "tag": "ul"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Endings matter. So here's mine. The right answer isn't the one with the biggest number at age 67. It's the one you and your partner can live with, calmly, for the next thirty years.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Frequently asked questions", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h2"}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Is it smart to pay off a home loan early in Malta?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h3"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "It can be, especially if the loan worries you or your rate is high. If your rate is low and you have a long time horizon, investing part of the money has historically offered more growth potential. Many people do both.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Can I lower my monthly repayment instead of shortening the loan?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h3"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Often, yes. Ask your bank whether a partial repayment can reduce the monthly instalment while keeping the same term, and whether any early repayment fee applies.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "What is dollar-cost averaging?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h3"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Investing a fixed amount at regular intervals, for example every month, instead of all at once. It spreads your entry over time and reduces the impact of investing just before a fall.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Should I invest a large sum all at once?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h3"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "There's no universal rule. Investing gradually can feel easier if you're new to markets and worried about short-term drops. The most important factor is staying invested long enough.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "heading", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "Want to understand investing properly, in Maltese?", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "tag": "h2"}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "My course ", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}, {"type": "link", "fields": {"linkType": "custom", "url": "/investing-made-simple/", "newTab": false}, "format": "", "indent": 0, "version": 3, "direction": "ltr", "children": [{"type": "text", "text": "Investing Made Simple", "format": 1, "detail": 0, "mode": "normal", "style": "", "version": 1}]}, {"type": "text", "text": " runs over four live Monday evenings from 11 January. €175 if you book by 31 December, €195 from 1 January.", "format": 0, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}, {"type": "paragraph", "format": "", "indent": 0, "version": 1, "direction": "ltr", "children": [{"type": "text", "text": "This article is for education only and is not financial or investment advice. Luca Caruana is a Certified Money Coach (CMC®). Money Coaching Hub does not sell financial products. Based on a reader question first answered in Luca's Money Coach column in the Times of Malta.", "format": 2, "detail": 0, "mode": "normal", "style": "", "version": 1}], "textFormat": 0, "textStyle": ""}]}} as const
const COVER_WEBP = ''

export async function up({ payload, req }: MigrateUpArgs): Promise<void> {
  if (process.env.VERCEL_ENV === 'preview') throw new Error('Blog article migration runs on the live site only.')

  const existing = await payload.find({ collection: 'posts', where: { slug: { equals: SLUG } }, limit: 1, depth: 0, draft: true, req })
  if (existing.docs.length) return

  const cat = await payload.find({ collection: 'categories', where: { slug: { equals: 'investment-coaching' } }, limit: 1, depth: 0, req })
  const categoryId = cat.docs[0]?.id
  if (!categoryId) throw new Error('Category investment-coaching not found')

  const data = Buffer.from(COVER_WEBP, 'base64')
  const media = await payload.create({
    collection: 'media',
    data: { alt: 'A couple on a sofa holding an inheritance envelope, weighing a paid-off house against an investment chart' },
    file: { data, mimetype: 'image/webp', name: `${SLUG}.webp`, size: data.length },
    req,
  })

  const post = await payload.create({
    collection: 'posts',
    draft: false,
    data: {
      title: 'Should I pay off my home loan early, or invest the money?',
      slug: SLUG,
      category: categoryId,
      featuredImage: media.id,
      excerpt: "Inherited money or savings? How to decide between paying off your home loan early and investing, and why time matters more than the amount.",
      content: CONTENT as any,
      publishedAt: new Date().toISOString(),
      _status: 'published',
      meta: {
        title: 'Pay off your home loan early or invest? | Money Coaching Hub',
        description: "Inherited money or savings? Here's how to decide between paying off your home loan early and investing, with a simple example of why time matters most.",
        image: media.id,
      },
    } as any,
    req,
  })

  const old = await payload.find({ collection: 'posts', where: { slug: { equals: OLD_SLUG } }, limit: 1, depth: 0, req })
  const oldPost = old.docs[0] as any
  if (oldPost) {
    await payload.update({ collection: 'posts', id: oldPost.id, data: { _status: 'draft' } as any, req })
    await payload.create({
      collection: 'redirects',
      data: { from: `/investment-coaching/${OLD_SLUG}/`, to: { type: 'reference', reference: { relationTo: 'posts', value: post.id } } } as any,
      req,
    })
  }
}

